import numpy as np

def feature(current, candidates, tour, start):
    """Distance from each candidate to the start city, normalized by the farthest candidate-to-start distance."""
    d_start = np.linalg.norm(candidates - start[None, :], axis=1)
    scale = np.max(d_start)
    if scale < 1e-9:
        return np.zeros(len(candidates))
    return d_start / scale

import numpy as np

def feature(current, candidates, tour, start):
    """Negative Euclidean distance from the current city to each candidate, normalised by the mean candidate distance."""
    d = np.linalg.norm(candidates - current, axis=1)
    return -d / (d.mean() + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Negative minimum distance from each candidate to any visited city, normalised by the mean of those minima."""
    d = np.linalg.norm(candidates[:, None, :] - tour[None, :, :], axis=2)  # (k, m)
    mind = d.min(axis=1)  # (k,)
    return -mind / (mind.mean() + 1e-9)

import numpy as np

def feature(current, candidates, tour, start):
    """Regret of each candidate: second-nearest minus nearest distance among the remaining candidates, normalised by its mean."""
    k = candidates.shape[0]
    if k < 3:
        return np.zeros(k)
    D = np.linalg.norm(candidates[:, None, :] - candidates[None, :, :], axis=2)
    np.fill_diagonal(D, np.inf)
    S = np.sort(D, axis=1)
    regret = S[:, 1] - S[:, 0]
    return regret / (regret.mean() + 1e-9)

