import numpy as np
def feature(current, candidates, tour, start):
    if len(tour) < 2:
        d = np.linalg.norm(candidates - tour[0], axis=1)
        return -d / (np.mean(d) + 1e-9)
    a = tour[:-1]; b = tour[1:]
    d_ac = np.linalg.norm(a[:,None,:] - candidates[None,:,:], axis=2)
    d_cb = np.linalg.norm(candidates[None,:,:] - b[:,None,:], axis=2)
    d_ab = np.linalg.norm(b - a, axis=1)
    cost = d_ac + d_cb - d_ab[:,None]
    best = cost.min(axis=0)
    return -best / (np.mean(best) + 1e-9)

